from collections import defaultdict
from datetime import date, datetime, timedelta
from typing import Optional

_WEEKS_TRACKED = 8
_TRAILING_WEEKS = 12


def _to_iso_week(d: datetime) -> str:
    iso = d.isocalendar()
    return f"{iso.year}-{iso.week:02d}"


def _parse_dt(v) -> datetime:
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    return datetime.fromisoformat(str(v).replace('Z', '+00:00')).replace(tzinfo=None)


def _iso_week_minus(d: date, weeks: int) -> date:
    return d - timedelta(weeks=weeks)


def cohort_retention(events: list, reference_week: Optional[date] = None) -> dict:
    by_user_weeks: dict[str, set] = defaultdict(set)
    first_week: dict[str, str] = {}

    for ev in events:
        uid = ev['user_id']
        dt = _parse_dt(ev['event_at'])
        wk = _to_iso_week(dt)
        by_user_weeks[uid].add(wk)
        if uid not in first_week or wk < first_week[uid]:
            first_week[uid] = wk

    # Cohort: first_week → users.
    cohorts: dict[str, list] = defaultdict(list)
    for uid, w in first_week.items():
        cohorts[w].append(uid)

    # Optional trailing-12-weeks filter.
    if reference_week is not None:
        cutoff = _to_iso_week(_parse_dt(_iso_week_minus(reference_week, _TRAILING_WEEKS)))
        cohorts = {k: v for k, v in cohorts.items() if k >= cutoff}

    cohort_size = {k: len(v) for k, v in cohorts.items()}

    # Index of week-after-cohort: pre-compute next-week strings.
    retention = {}
    for cohort_wk, users in cohorts.items():
        sz = len(users)
        row = {}
        for k in range(_WEEKS_TRACKED):
            target_wk = _shift_iso_week(cohort_wk, k)
            count = sum(1 for u in users if target_wk in by_user_weeks[u])
            row[f'week_{k}_pct'] = (count / sz) if sz > 0 else 0.0
        retention[cohort_wk] = row

    return {'cohort_size': cohort_size, 'retention': retention}


def _shift_iso_week(yyyyww: str, weeks: int) -> str:
    year, wk = yyyyww.split('-')
    # Approximate: take Monday of the ISO week, shift, return.
    monday = datetime.fromisocalendar(int(year), int(wk), 1) + timedelta(weeks=weeks)
    return _to_iso_week(monday)
